#!/bin/bash
# gen.sh <position> <mode>  -> emits B64: lines for every printable ASCII char 0x20..0x7E
# mode: raw | pct
pos="$1"; mode="$2"
lo=$((0x20)); hi=$((0x7E))
if [ -n "$3" ]; then lo=$((0x$3)); fi
if [ -n "$4" ]; then hi=$((0x$4)); fi
i=$lo
while [ $i -le $hi ]; do
  hex=$(printf '%02X' $i)
  if [ "$mode" = "pct" ]; then
    c="%$hex"
  else
    c=$(printf "\\x$hex")
  fi
  case "$pos" in
    scheme)  a="ht${c}tp://a.com/p" ;;
    schemepre) a="${c}http://a.com/p" ;;
    path)    a="http://a.com/p${c}q/r" ;;
    qkey)    a="http://a.com/p?k${c}y=v" ;;
    qval)    a="http://a.com/p?k=v${c}w" ;;
    frag)    a="http://a.com/p#f${c}g" ;;
    user)    a="http://us${c}er:pw@a.com/p" ;;
    pass)    a="http://user:p${c}w@a.com/p" ;;
    hostb)   a="http://a.com/p" ;;
  esac
  if [ "$pos" = "hostb" ]; then
    printf 'B64:%s\t%s\n' "$(printf '%s' "$a" | base64 -w0)" "$(printf '%s' "n${c}com" | base64 -w0)"
  else
    printf 'B64:%s\t%s\n' "$(printf '%s' "$a" | base64 -w0)" "$(printf '%s' "n.com" | base64 -w0)"
  fi
  i=$((i+1))
done
